import bpy, os, math
import numpy as np

# Clear default scene
bpy.ops.object.select_all(action='SELECT')
bpy.ops.object.delete(use_global=False)
for d in (bpy.data.meshes, bpy.data.curves, bpy.data.materials, bpy.data.cameras, bpy.data.lights):
    for b in list(d):
        try: d.remove(b)
        except: pass

# Analysis: for each image, classify pixels by color class, report bbox & centroid
names = [f"render_{i:04d}.png" for i in range(11)]
W=H=768

def classify(r,g,b):
    # r,g,b in 0..1 floats
    mx, mn = max(r,g,b), min(r,g,b)
    if mx<0.12: return 'black'          # TV
    if mx>0.9 and (mx-mn)<0.05: return None  # white bg
    if g>r*1.15 and g>b*1.1 and g>0.5: return 'green'  # sofa / pillow
    if r>0.7 and b>0.6 and g<0.6: return 'pink'  # chair upholstery
    if r>0.35 and g<0.28 and b<0.28: return 'darkbrown' # blanket / dark wood
    if r>0.6 and g>0.45 and b<0.3: return 'tan'  # light wood / brass
    return None

results={}
for n in names:
    img = bpy.data.images.load(f'/app/input/{n}')
    px = np.array(img.pixels[:], dtype=np.float32).reshape(H,W,4)
    cls = {}
    for cname in ['green','pink','darkbrown','black','tan']:
        cls[cname]={'count':0,'minx':W,'maxx':-1,'miny':H,'maxy':-1,'sx':0,'sy':0}
    # sample every 2 px for speed
    sub = px[::2,::2,:3]
    sh,sw,_ = sub.shape
    for iy in range(sh):
        row = sub[iy]
        for ix in range(sw):
            c = classify(*row[ix])
            if c:
                d=cls[c]; d['count']+=1
                x,y = ix*2, iy*2
                d['minx']=min(d['minx'],x); d['maxx']=max(d['maxx'],x)
                d['miny']=min(d['miny'],y); d['maxy']=max(d['maxy'],y)
                d['sx']+=x; d['sy']+=y
    results[n]={}
    for c,d in cls.items():
        if d['count']>30:
            results[n][c]={'count':d['count'],'bbox':(d['minx'],d['miny'],d['maxx'],d['maxy']),
                           'centroid':(d['sx']/d['count'], d['sy']/d['count'])}
for n in names:
    print(n, results[n])

import bpy, numpy as np

def find_clusters(name):
    img=bpy.data.images.load(f'/app/input/{name}')
    px=np.array(img.pixels[:],dtype=np.float32).reshape(768,768,4)[::-1,:,:3]*255  # now top-origin
    r,g,b = px[:,:,0],px[:,:,1],px[:,:,2]
    dark = (r<60)&(g<60)&(b<60)
    magenta = (r>120)&(b>100)&(g<0.65*r)&((r-g)>40)
    res={}
    for nm,m in [('dark',dark),('magenta',magenta)]:
        ys,xs=np.where(m)
        if len(xs)>50:
            res[nm]=(int(xs.min()),int(ys.min()),int(xs.max()),int(ys.max()),int(len(xs)))
        else:
            res[nm]=None
    return res

for i in range(11):
    n=f'render_{i:04d}.png'
    print(n, find_clusters(n))
